def generate_sentences(synonyms, text):
    parent = {}

    def find(x):
        parent.setdefault(x, x)
        while parent[x] != x:
            parent[x] = parent[parent[x]]        # path halving
            x = parent[x]
        return x

    for a, b in synonyms:
        parent[find(a)] = find(b)
    groups = defaultdict(list)
    for w in parent:
        groups[find(w)].append(w)
    for g in groups.values():
        g.sort()

    words, out, path = text.split(), [], []

    def dfs(i):
        if i == len(words):
            out.append(" ".join(path))
            return
        w = words[i]
        for option in (groups[find(w)] if w in parent else [w]):
            path.append(option)                  # choose
            dfs(i + 1)                           # explore
            path.pop()                           # un-choose

    dfs(0)
    return out

def generate_sentences(synonyms, text):
    graph = defaultdict(set)
    for a, b in synonyms:
        graph[a].add(b)
        graph[b].add(a)
    seen, queue = {text}, deque([text])
    while queue:
        words = queue.popleft().split()
        for i, w in enumerate(words):
            for alt in graph[w]:
                nxt = " ".join(words[:i] + [alt] + words[i + 1:])
                if nxt not in seen:
                    seen.add(nxt)
                    queue.append(nxt)
    return sorted(seen)
